"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": timedelta(0),
           "compress_after": 1, "keep": 5, "keep_days": None}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_AGE = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_INT = re.compile(r"[0-9]+\Z")
_STREAM = re.compile(r"\[stream ([^\]]*)\]\Z")


def _bad(msg):
    raise DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        _bad(f"bad size {v!r}")
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _age(v):
    if v == "off":
        return None
    m = _AGE.match(v)
    if not m:
        _bad(f"bad duration {v!r}")
    return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})


def _naming(v):
    if v not in ("numbered", "dated"):
        _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        _bad(f"bad offset {v!r}")
    d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -d if m.group(1) == "-" else d


def _count(minimum, allow_off):
    def parse(v):
        if allow_off and v == "off":
            return None
        if not _INT.match(v) or int(v) < minimum:
            _bad(f"bad number {v!r}")
        return int(v)
    return parse


PARSERS = {"max_size": _size, "max_age": _age, "naming": _naming, "offset": _offset,
           "compress_after": _count(0, False), "keep": _count(1, False), "keep_days": _count(1, True)}


class Policy:
    def __init__(self, defaults=None, sections=None):
        self.defaults = defaults or {}
        self.sections = sections or {}

    def for_stream(self, name) -> dict:
        out = dict(BUILTIN)
        out.update(self.defaults)
        out.update(self.sections.get(name, {}))
        return out


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy()
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"policy.ini: {e}") from None
    defaults, sections, current, seen = None, {}, None, set()
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if line == "[defaults]":
                key = ("defaults",)
                if key in seen:
                    _bad("section twice")
                seen.add(key)
                defaults = current = {}
            else:
                m = _STREAM.match(line)
                if not m or not streams.valid(m.group(1)):
                    _bad(f"bad section {line!r}")
                key = ("stream", m.group(1))
                if key in seen:
                    _bad("section twice")
                seen.add(key)
                current = sections[m.group(1)] = {}
            continue
        if current is None or "=" not in line:
            _bad(f"bad line {line!r}")
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip()
        if k not in PARSERS:
            _bad(f"unknown key {k!r}")
        if k in current:
            _bad(f"key {k} twice")
        current[k] = PARSERS[k](v)
    return Policy(defaults, sections)
