"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused

_OLD_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_ISO_TIME = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})\Z")


def parse_time(text):
    """An instant from a time of data.md section 2, or None."""
    if not isinstance(text, str):
        return None
    try:
        if _OLD_TIME.match(text):
            return datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        if _ISO_TIME.match(text):
            t = datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith("Z") else text)
            return t if t.tzinfo is not None else None
    except ValueError:
        return None
    return None


class Archive:
    def __init__(self, old, gz, age, day=None, k=1):
        self.old, self.gz, self.age, self.day, self.k = old, gz, age, day, k
        self.final_gz = gz
        self.name = old


def _day(text):
    try:
        return date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def scan(files, name, naming):
    """Archives of the stream, and the places used twice."""
    e = re.escape(name)
    if naming == "numbered":
        rx = re.compile(rf"{e}\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(rf"{e}\.log\.([0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")
    found, dup = {}, False
    for f in files:
        m = rx.match(f)
        if not m:
            continue
        if naming == "numbered":
            place, gz = (int(m.group(1)),), bool(m.group(2))
            a = Archive(f, gz, (-int(m.group(1)),))
        else:
            d = _day(m.group(1))
            if d is None:
                continue
            k = int(m.group(2)) if m.group(2) else 1
            place, gz = (d, k), bool(m.group(3))
            a = Archive(f, gz, (d.toordinal(), k), d, k)
        if place in found:
            dup = True
        found[place] = a
    return found, dup


def _first_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
        return parse_time(line.rstrip(b"\n").decode("utf-8").split(" ", 1)[0])
    except (OSError, UnicodeDecodeError):
        return None


def run(ctx, names, dry, force):
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    data = ctx.data
    logs = streams.logs_dir(data)
    files = sorted(p.name for p in logs.iterdir() if p.is_file()) if logs.is_dir() else []
    existing = set(streams.active(data)) | set(pol.sections)

    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and parse_time(entry["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict) or any(parse_time(v) is None for v in arch.values()):
                raise DataError("state", f"{name}: bad archives")
        if "rotations" in entry:
            r = entry["rotations"]
            if not isinstance(r, int) or isinstance(r, bool) or r < 0:
                raise DataError("state", f"{name}: bad rotations")

    if names:
        names = sorted(set(names))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)

    plans = []
    for name in names:
        s = pol.for_stream(name)
        found, dup = scan(files, name, s["naming"])
        if dup:
            raise DataError("archives", f"{name}: two archives in the same place")
        plans.append((name, s, list(found.values())))

    now = ctx.now
    now_stamp = ctx.stamp
    out, reads, removes, writes, entries = [], [], [], [], {}
    n_rot = n_rem = n_comp = 0
    for name, s, archives in plans:
        entry = doc["streams"].get(name, {})
        times = {k: v for k, v in entry.get("archives", {}).items()}
        log = streams.log_path(data, name)
        what = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what = "rotate (forced)"
            elif s["max_size"] is not None and size >= s["max_size"]:
                what = "rotate (size)"
            elif s["max_age"] is not None:
                opened = parse_time(entry["opened"]) if "opened" in entry else _first_time(log)
                if opened is not None and now - opened >= s["max_age"]:
                    what = "rotate (age)"
            if what is None:
                what = "not due"
        rotated = what.startswith("rotate")
        new = None
        if rotated:
            n_rot += 1
            if s["naming"] == "dated":
                day = now.astimezone(timezone(s["offset"])).date()
                ks = [a.k for a in archives if a.day == day]
                k = 1
                if ks:
                    k = 2
                    while k in ks:
                        k += 1
                new = Archive(None, False, (day.toordinal(), k), day, k)
            else:
                new = Archive(None, False, (0,))
            archives.append(new)
        archives.sort(key=lambda a: a.age, reverse=True)

        def tm(a):
            if a is new:
                return now
            return parse_time(times[a.old]) if a.old in times else None

        keep, removed, remaining = s["keep"], [], []
        for pos, a in enumerate(archives, 1):
            t = tm(a)
            if pos > keep or (s["keep_days"] is not None and t is not None
                              and now - t >= timedelta(days=s["keep_days"])):
                removed.append(a)
            else:
                remaining.append(a)
        out.append(f"{name}: {what}")
        new_times = {}
        for j, a in enumerate(remaining, 1):
            a.final_gz = a.gz or j > s["compress_after"]
            if s["naming"] == "numbered":
                base = f"{name}.log.{j}"
            else:
                base = f"{name}.log.{a.day.isoformat()}" + (f".{a.k}" if a.k > 1 else "")
            a.name = base + (".gz" if a.final_gz else "")
            if a.final_gz and not a.gz:
                n_comp += 1
            if a is new:
                out.append(f"  new {a.name}")
                new_times[a.name] = now_stamp
            else:
                out.append(f"  {a.name}" if a.name == a.old else f"  {a.name} <- {a.old}")
                if a.old in times:
                    new_times[a.name] = times[a.old]
        if new is not None and new in removed:
            n_rec = new.name
        for a in removed:
            if a is new:
                out.append(f"  remove {name}.log.{a.day.isoformat()}" + (f".{a.k}" if a.k > 1 else ""))
            else:
                out.append(f"  remove {a.old}")
        n_rem += len(removed)

        # file operations
        if rotated:
            content = log.read_bytes()
            if new in remaining:
                payload = gzip.compress(content, mtime=0) if new.final_gz else content
                writes.append((logs / new.name, payload))
            writes.append((log, b""))
        for a in removed:
            if a is not new:
                removes.append(logs / a.old)
        for a in remaining:
            if a is new:
                continue
            if a.name != a.old or a.final_gz != a.gz:
                path = logs / a.old
                reads.append((path, logs / a.name, a.final_gz and not a.gz))
        new_entry = {}
        if rotated:
            new_entry["opened"] = now_stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = new_times
        entries[name] = new_entry
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")

    if dry:
        out.append("dry run: nothing written")
        return out

    loaded = []
    for src, dst, comp in reads:
        b = src.read_bytes()
        loaded.append((dst, gzip.compress(b, mtime=0) if comp else b))
    for src, _, _ in reads:
        src.unlink()
    for p in removes:
        p.unlink()
    for p, b in loaded + writes:
        p.write_bytes(b)
    doc["streams"].update(entries)
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state_mod.save(ctx.state_path, doc)
    return out
