                removed.append(a)
            else:
                remaining.append(a)
        out.append(f"{name}: {what}")
        new_times = {}
        for j, a in enumerate(remaining, 1):
            a.final_gz = a.gz or j > s["compress_after"]
            if s["naming"] == "numbered":
                base = f"{name}.log.{j}"
            else:
                base = f"{name}.log.{a.day.isoformat()}" + (f".{a.k}" if a.k > 1 else "")
            a.name = base + (".gz" if a.final_gz else "")
            if a.final_gz and not a.gz:
                n_comp += 1
            if a is new:
                out.append(f"  new {a.name}")
                new_times[a.name] = now_stamp
            else:
                out.append(f"  {a.name}" if a.name == a.old else f"  {a.name} <- {a.old}")
                if a.old in times:
                    new_times[a.name] = times[a.old]
        if new is not None and new in removed:
            n_rec = new.name
        for a in removed:
            if a is new:
                out.append(f"  remove {name}.log.{a.day.isoformat()}" + (f".{a.k}" if a.k > 1 else ""))
            else:
                out.append(f"  remove {a.old}")
        n_rem += len(removed)

        # file operations
        if rotated:
            content = log.read_bytes()
            if new in remaining:
                payload = gzip.compress(content, mtime=0) if new.final_gz else content
                writes.append((logs / new.name, payload))
            writes.append((log, b""))
        for a in removed:
            if a is not new:
                removes.append(logs / a.old)
        for a in remaining:
            if a is new:
                continue
            if a.name != a.old or a.final_gz != a.gz:
                path = logs / a.old
                reads.append((path, logs / a.name, a.final_gz and not a.gz))
        new_entry = {}
        if rotated:
            new_entry["opened"] = now_stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = new_times
        entries[name] = new_entry
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")

    if dry:
        out.append("dry run: nothing written")
        return out

    loaded = []
    for src, dst, comp in reads:
        b = src.read_bytes()
        loaded.append((dst, gzip.compress(b, mtime=0) if comp else b))
    for src, _, _ in reads:
        src.unlink()
    for p in removes:
        p.unlink()
    for p, b in loaded + writes:
        p.write_bytes(b)
    doc["streams"].update(entries)
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state_mod.save(ctx.state_path, doc)
    return out
